-- ---------------------------------------------------------------------------
-- Condition modifiers
-- ---------------------------------------------------------------------------

-- The source catalog records one factor plus a slash-separated target list
-- ("0.88 / Labor+Production"), which is ambiguous about whether labor gets
-- 12% slower or 12% cheaper. Each modifier is therefore expanded here into an
-- explicit factor per target so it can only mean what it is written to mean.
-- Production entries carry the catalog factor as a rate multiplier; the five
-- Section 7.1 cost modifiers carry their surcharge as a cost multiplier.

insert into condition_modifiers (code, name, category, factors, application_rule, status) values
  ('MOD-ACCESS', 'Restricted access', 'Production', '{"production":0.75}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-WEATHER', 'Adverse weather', 'Production', '{"production":0.8}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-WINTER', 'Winter conditions', 'Production', '{"production":0.7}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-PHASE', 'Multi-phase work', 'Production', '{"production":0.85}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-NIGHT', 'Night work', 'Labor/Production', '{"labor_cost":1.12,"production":0.88}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-TRAFFIC', 'Traffic control', 'Production/Indirect', '{"production":0.8,"indirect_cost":1.2}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-CONG', 'Congestion', 'Production', '{"production":0.78}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-DIFF', 'Difficult material', 'Production/Equipment', '{"production":0.65,"equipment_cost":1.35}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-GW', 'Groundwater', 'Production/Indirect', '{"production":0.7,"indirect_cost":1.3}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-CONT', 'Contaminated material', 'Production/Disposal', '{"production":0.6,"disposal_cost":1.4}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-DEEP', 'Deep excavation', 'Production/Safety', '{"production":0.7,"schedule":0.7}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-SHORE', 'Shoring required', 'Production/Material', '{"production":0.75,"material_cost":1.25}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-DEW', 'Dewatering required', 'Production/Equipment', '{"production":0.8,"equipment_cost":1.2}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-SMALL', 'Small quantity inefficiency', 'Production', '{"production":0.65}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-ACCEL', 'Accelerated schedule', 'Labor/Equipment', '{"labor_cost":1.2,"equipment_cost":1.2}'::jsonb, 'Explicit estimator selection with explanation', 'active'),
  ('MOD-WET-SOIL', 'Wet soil', 'Section 7.1', '{"labor_cost":1.15,"production":0.85}'::jsonb, 'Geotechnical report or field observation indicates saturated soil', 'active'),
  ('MOD-ROCK', 'Rock', 'Section 7.1', '{"labor_cost":1.35,"equipment_cost":1.35,"production":0.65}'::jsonb, 'Rock indicated by boring logs or observed in excavation', 'active'),
  ('MOD-TIGHT-ACCESS', 'Tight access', 'Section 7.1', '{"equipment_cost":1.2,"production":0.8}'::jsonb, 'Working room restricts equipment size or movement', 'active'),
  ('MOD-WINTER-COST', 'Winter conditions (cost)', 'Section 7.1', '{"labor_cost":1.12}'::jsonb, 'Work scheduled during winter months', 'active'),
  ('MOD-NIGHT-COST', 'Night work (cost)', 'Section 7.1', '{"labor_cost":1.18,"production":0.88}'::jsonb, 'Owner or agency requires night work', 'active')
on conflict do nothing;


